SET NAMES utf8mb4;
CREATE TABLE roles (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(40) NOT NULL UNIQUE);
CREATE TABLE permissions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(80) NOT NULL UNIQUE);
CREATE TABLE role_permissions (role_id BIGINT UNSIGNED NOT NULL, permission_id BIGINT UNSIGNED NOT NULL, PRIMARY KEY(role_id,permission_id), FOREIGN KEY(role_id) REFERENCES roles(id), FOREIGN KEY(permission_id) REFERENCES permissions(id));
CREATE TABLE users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, auth_id CHAR(36) NOT NULL UNIQUE, email VARCHAR(254) NOT NULL, name VARCHAR(160) NOT NULL, role_id BIGINT UNSIGNED NOT NULL, active BOOLEAN NOT NULL DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(role_id) REFERENCES roles(id));
CREATE TABLE clients (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(160) NOT NULL, email VARCHAR(254) NOT NULL, company VARCHAR(160) NOT NULL DEFAULT '', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE client_users (client_id BIGINT UNSIGNED NOT NULL, user_id BIGINT UNSIGNED NOT NULL, PRIMARY KEY(client_id,user_id), FOREIGN KEY(client_id) REFERENCES clients(id), FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE pages (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, slug VARCHAR(100) NOT NULL UNIQUE, title VARCHAR(160) NOT NULL, summary TEXT NOT NULL, body MEDIUMTEXT NOT NULL, status ENUM('draft','published') NOT NULL DEFAULT 'draft', seo_title VARCHAR(160) NOT NULL DEFAULT '', seo_description VARCHAR(300) NOT NULL DEFAULT '', version INT NOT NULL DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE content_versions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, resource VARCHAR(50) NOT NULL, record_id BIGINT UNSIGNED NOT NULL, version INT NOT NULL, snapshot JSON NOT NULL, user_id BIGINT UNSIGNED NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, UNIQUE(resource,record_id,version), FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE services (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, slug VARCHAR(100) NOT NULL UNIQUE, title VARCHAR(160) NOT NULL, summary TEXT NOT NULL, body MEDIUMTEXT NOT NULL, status ENUM('draft','published') NOT NULL DEFAULT 'draft', version INT NOT NULL DEFAULT 1);
CREATE TABLE projects (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, client_id BIGINT UNSIGNED NOT NULL, slug VARCHAR(100) NOT NULL UNIQUE, title VARCHAR(160) NOT NULL, summary TEXT NOT NULL, body MEDIUMTEXT NOT NULL, location VARCHAR(160) NOT NULL, category VARCHAR(80) NOT NULL, budget DECIMAL(16,2) NOT NULL DEFAULT 0, currency CHAR(3) NOT NULL DEFAULT 'INR', progress INT NOT NULL DEFAULT 0, state ENUM('planning','active','completed','on-hold') NOT NULL DEFAULT 'planning', completion_date DATE NULL, public BOOLEAN NOT NULL DEFAULT 0, version INT NOT NULL DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, CHECK(progress BETWEEN 0 AND 100), CHECK(budget>=0), FOREIGN KEY(client_id) REFERENCES clients(id));
CREATE TABLE milestones (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, project_id BIGINT UNSIGNED NOT NULL, title VARCHAR(160) NOT NULL, due_date DATE NOT NULL, completed BOOLEAN NOT NULL DEFAULT 0, FOREIGN KEY(project_id) REFERENCES projects(id));
CREATE TABLE project_records (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, project_id BIGINT UNSIGNED NOT NULL, kind ENUM('report','meeting','rfi','snag','approval','risk') NOT NULL, title VARCHAR(160) NOT NULL, body TEXT NOT NULL, status ENUM('open','in-progress','closed','approved','rejected') NOT NULL DEFAULT 'open', due_date DATE NULL, created_by BIGINT UNSIGNED NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(project_id) REFERENCES projects(id), FOREIGN KEY(created_by) REFERENCES users(id));
CREATE TABLE invoices (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, project_id BIGINT UNSIGNED NOT NULL, number VARCHAR(80) NOT NULL UNIQUE, currency CHAR(3) NOT NULL DEFAULT 'INR', due_date DATE NOT NULL, status ENUM('draft','issued','paid','void') NOT NULL DEFAULT 'draft', FOREIGN KEY(project_id) REFERENCES projects(id));
CREATE TABLE invoice_items (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, invoice_id BIGINT UNSIGNED NOT NULL, description VARCHAR(300) NOT NULL, quantity DECIMAL(12,3) NOT NULL, unit_price DECIMAL(14,2) NOT NULL, tax_percent DECIMAL(5,2) NOT NULL DEFAULT 0, CHECK(quantity>0), CHECK(unit_price>=0), CHECK(tax_percent BETWEEN 0 AND 100), FOREIGN KEY(invoice_id) REFERENCES invoices(id));
CREATE TABLE payments (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, invoice_id BIGINT UNSIGNED NOT NULL, provider VARCHAR(40) NOT NULL, provider_reference VARCHAR(160) NOT NULL UNIQUE, amount DECIMAL(16,2) NOT NULL, currency CHAR(3) NOT NULL, status VARCHAR(30) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(invoice_id) REFERENCES invoices(id));
CREATE TABLE documents (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, project_id BIGINT UNSIGNED NOT NULL, title VARCHAR(160) NOT NULL, object_path VARCHAR(500) NOT NULL UNIQUE, mime VARCHAR(100) NOT NULL, size_bytes BIGINT UNSIGNED NOT NULL, uploaded_by BIGINT UNSIGNED NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(project_id) REFERENCES projects(id), FOREIGN KEY(uploaded_by) REFERENCES users(id));
CREATE TABLE leads (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(160) NOT NULL, email VARCHAR(254) NOT NULL, phone VARCHAR(40) NOT NULL DEFAULT '', service VARCHAR(160) NOT NULL, message TEXT NOT NULL, consent_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, status ENUM('new','contacted','qualified','won','lost') NOT NULL DEFAULT 'new', assigned_to BIGINT UNSIGNED NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(assigned_to) REFERENCES users(id));
CREATE TABLE appointments (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, lead_id BIGINT UNSIGNED NOT NULL, starts_at DATETIME NOT NULL, ends_at DATETIME NOT NULL, status ENUM('requested','confirmed','cancelled') NOT NULL DEFAULT 'requested', UNIQUE(starts_at), CHECK(ends_at>starts_at), FOREIGN KEY(lead_id) REFERENCES leads(id));
CREATE TABLE newsletter (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, email VARCHAR(254) NOT NULL UNIQUE, status ENUM('pending','subscribed','unsubscribed') NOT NULL DEFAULT 'pending', token_hash CHAR(64) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE settings (`key` VARCHAR(80) PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE audit_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NULL, action VARCHAR(80) NOT NULL, resource VARCHAR(80) NOT NULL, record_id BIGINT UNSIGNED NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE rate_limits (bucket CHAR(64) PRIMARY KEY, hits INT UNSIGNED NOT NULL, expires_at BIGINT UNSIGNED NOT NULL);
CREATE TABLE notifications (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, title VARCHAR(160) NOT NULL, body TEXT NOT NULL, read_at DATETIME NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE outbox (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, event_type VARCHAR(80) NOT NULL, payload JSON NOT NULL, status ENUM('pending','sent','failed') NOT NULL DEFAULT 'pending', attempts INT NOT NULL DEFAULT 0, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE categories (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL, slug VARCHAR(100) NOT NULL UNIQUE);
CREATE TABLE tags (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL, slug VARCHAR(100) NOT NULL UNIQUE);
CREATE TABLE blog (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, category_id BIGINT UNSIGNED NULL, slug VARCHAR(100) NOT NULL UNIQUE, title VARCHAR(160) NOT NULL, summary TEXT NOT NULL, body MEDIUMTEXT NOT NULL, status ENUM('draft','published') NOT NULL DEFAULT 'draft', version INT NOT NULL DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(category_id) REFERENCES categories(id));
CREATE TABLE blog_tags (blog_id BIGINT UNSIGNED NOT NULL, tag_id BIGINT UNSIGNED NOT NULL, PRIMARY KEY(blog_id,tag_id), FOREIGN KEY(blog_id) REFERENCES blog(id), FOREIGN KEY(tag_id) REFERENCES tags(id));
CREATE TABLE media (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, title VARCHAR(160) NOT NULL, url VARCHAR(500) NOT NULL, alt_text VARCHAR(300) NOT NULL, kind ENUM('photo','video','panorama') NOT NULL);
CREATE TABLE gallery (project_id BIGINT UNSIGNED NOT NULL, media_id BIGINT UNSIGNED NOT NULL, PRIMARY KEY(project_id,media_id), FOREIGN KEY(project_id) REFERENCES projects(id), FOREIGN KEY(media_id) REFERENCES media(id));
CREATE TABLE portfolio (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, project_id BIGINT UNSIGNED NOT NULL, title VARCHAR(160) NOT NULL, summary TEXT NOT NULL, body MEDIUMTEXT NOT NULL, status ENUM('draft','published') NOT NULL DEFAULT 'draft', version INT NOT NULL DEFAULT 1, FOREIGN KEY(project_id) REFERENCES projects(id));
CREATE TABLE testimonials (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, client_id BIGINT UNSIGNED NOT NULL, name VARCHAR(160) NOT NULL, company VARCHAR(160) NOT NULL, quote TEXT NOT NULL, status ENUM('draft','published') NOT NULL DEFAULT 'draft', version INT NOT NULL DEFAULT 1, FOREIGN KEY(client_id) REFERENCES clients(id));
CREATE TABLE forms (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(160) NOT NULL, schema_json JSON NOT NULL, active BOOLEAN NOT NULL DEFAULT 1);
CREATE TABLE seo (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, path VARCHAR(200) NOT NULL UNIQUE, title VARCHAR(160) NOT NULL, description VARCHAR(300) NOT NULL, noindex BOOLEAN NOT NULL DEFAULT 0);
CREATE INDEX project_client ON projects(client_id);
CREATE INDEX project_public ON projects(public,category,location);
CREATE INDEX record_project ON project_records(project_id,kind,status);
CREATE INDEX lead_status ON leads(status,created_at);
CREATE INDEX page_public ON pages(status,slug);
CREATE INDEX blog_public ON blog(status,slug);
